CREATE TABLE IF NOT EXISTS families (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS people (id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, display_name TEXT NOT NULL, birth_date TEXT, relationship_type TEXT NOT NULL, generation INTEGER NOT NULL, branch TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS relations (id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, from_person_id TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, to_person_id TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, relation_type TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS locations (id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, label TEXT NOT NULL, address TEXT, latitude REAL, longitude REAL, kind TEXT NOT NULL, created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, kind TEXT NOT NULL, title TEXT NOT NULL, description TEXT, start_at TEXT NOT NULL, location_id TEXT REFERENCES locations(id) ON DELETE SET NULL, location_label TEXT, visibility TEXT NOT NULL, participant_person_ids TEXT NOT NULL, invitation_text TEXT, notes TEXT, attachment_count INTEGER NOT NULL DEFAULT 0, ai_processing_allowed INTEGER NOT NULL DEFAULT 0, recurrence TEXT NOT NULL DEFAULT 'none', reminder_days TEXT NOT NULL DEFAULT '[7,1]', created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, display_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_record TEXT NOT NULL, failed_login_count INTEGER NOT NULL DEFAULT 0, locked_until TEXT, totp_secret TEXT, recovery_codes TEXT, pending_totp_secret TEXT, pending_recovery_codes TEXT, created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS archive_items (id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, title TEXT NOT NULL, original_name TEXT NOT NULL, stored_name TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, linked_event_id TEXT REFERENCES events(id) ON DELETE SET NULL, created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, occurred_at TEXT NOT NULL, actor_id TEXT, prev_hash TEXT, entry_hash TEXT);
      CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY,email TEXT NOT NULL,role TEXT NOT NULL,person_id TEXT REFERENCES people(id) ON DELETE SET NULL,starts_at TEXT NOT NULL,ends_at TEXT,status TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL,accepted_at TEXT);
      CREATE TABLE IF NOT EXISTS object_permissions (id TEXT PRIMARY KEY,subject_account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,actions TEXT NOT NULL,effect TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS finance_records (id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,owner_person_id TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,title TEXT NOT NULL,kind TEXT NOT NULL,amount REAL NOT NULL,currency TEXT NOT NULL,privacy TEXT NOT NULL,notes TEXT,occurred_at TEXT NOT NULL,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS health_records (id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,owner_person_id TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,title TEXT NOT NULL,kind TEXT NOT NULL,privacy TEXT NOT NULL,provider TEXT,notes TEXT,occurred_at TEXT NOT NULL,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS medication_plans (id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,owner_person_id TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,name TEXT NOT NULL,dosage TEXT NOT NULL,schedule TEXT NOT NULL,provider TEXT,starts_at TEXT NOT NULL,ends_at TEXT,privacy TEXT NOT NULL,notes TEXT,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS family_health_history (id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,related_person_id TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,condition TEXT NOT NULL,relationship_note TEXT,diagnosed_at TEXT,privacy TEXT NOT NULL,notes TEXT,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS life_records (id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,owner_person_id TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,category TEXT NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL,privacy TEXT NOT NULL,starts_at TEXT,due_at TEXT,provider TEXT,reference_no TEXT,amount REAL,currency TEXT,location TEXT,notes TEXT,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS finance_valuations (id TEXT PRIMARY KEY,finance_record_id TEXT NOT NULL REFERENCES finance_records(id) ON DELETE CASCADE,value_date TEXT NOT NULL,unit_price REAL NOT NULL,quantity REAL NOT NULL,market_value REAL NOT NULL,provider TEXT NOT NULL,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS automation_rules (id TEXT PRIMARY KEY,title TEXT NOT NULL,source_type TEXT NOT NULL,days_before INTEGER NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS automation_runs (id TEXT PRIMARY KEY,rule_id TEXT NOT NULL REFERENCES automation_rules(id) ON DELETE CASCADE,source_type TEXT NOT NULL,source_id TEXT NOT NULL,title TEXT NOT NULL,due_at TEXT NOT NULL,status TEXT NOT NULL,generated_task_id TEXT,created_at TEXT NOT NULL,UNIQUE(rule_id,source_type,source_id));
      CREATE TABLE IF NOT EXISTS digital_legacy_plans (id TEXT PRIMARY KEY,owner_person_id TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,title TEXT NOT NULL,status TEXT NOT NULL,trigger_type TEXT NOT NULL,trustee_account_id TEXT NOT NULL REFERENCES accounts(id),secondary_trustee_account_id TEXT REFERENCES accounts(id),instructions TEXT,starts_at TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS legacy_grants (id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES digital_legacy_plans(id) ON DELETE CASCADE,resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,actions TEXT NOT NULL,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS legacy_approvals (id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES digital_legacy_plans(id) ON DELETE CASCADE,approver_account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,decision TEXT NOT NULL,note TEXT,created_at TEXT NOT NULL,UNIQUE(plan_id,approver_account_id));
      CREATE TABLE IF NOT EXISTS archive_categories (id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE,description TEXT,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS archive_tags (id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS archive_item_tags (archive_item_id TEXT NOT NULL REFERENCES archive_items(id) ON DELETE CASCADE,tag_id TEXT NOT NULL REFERENCES archive_tags(id) ON DELETE CASCADE,PRIMARY KEY(archive_item_id,tag_id));
      CREATE TABLE IF NOT EXISTS archive_versions (id TEXT PRIMARY KEY,archive_item_id TEXT NOT NULL REFERENCES archive_items(id) ON DELETE CASCADE,version_no INTEGER NOT NULL,original_name TEXT NOT NULL,mime_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL,note TEXT,UNIQUE(archive_item_id,version_no));
      CREATE TABLE IF NOT EXISTS archive_retention_policies (id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE,retention_days INTEGER NOT NULL,secure_destroy INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS backup_targets (id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,path TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,last_success_at TEXT,last_verified_at TEXT,last_error TEXT,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS diagnostic_entries (id TEXT PRIMARY KEY,severity TEXT NOT NULL,code TEXT NOT NULL,message TEXT NOT NULL,details TEXT,occurred_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS backup_runs (id TEXT PRIMARY KEY,target_id TEXT NOT NULL REFERENCES backup_targets(id) ON DELETE CASCADE,status TEXT NOT NULL,file_path TEXT,size_bytes INTEGER,sha256 TEXT,free_bytes INTEGER,error TEXT,started_at TEXT NOT NULL,completed_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS performance_samples (id TEXT PRIMARY KEY,cpu_load_percent REAL NOT NULL,memory_usage_percent REAL NOT NULL,database_bytes INTEGER NOT NULL,archive_bytes INTEGER NOT NULL,sampled_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS background_tasks (id TEXT PRIMARY KEY,task_type TEXT NOT NULL,label TEXT NOT NULL,status TEXT NOT NULL,started_at TEXT NOT NULL,completed_at TEXT,duration_ms INTEGER,warning_threshold_ms INTEGER NOT NULL DEFAULT 30000,details TEXT);
      CREATE TABLE IF NOT EXISTS task_queue (id TEXT PRIMARY KEY,task_type TEXT NOT NULL,label TEXT NOT NULL,priority TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,started_at TEXT,completed_at TEXT,attempts INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL DEFAULT 2,payload TEXT,details TEXT);
      CREATE TABLE IF NOT EXISTS maintenance_policy (id TEXT PRIMARY KEY,enabled INTEGER NOT NULL,interval_hours INTEGER NOT NULL,keep_diagnostic_days INTEGER NOT NULL,keep_performance_days INTEGER NOT NULL,next_run_at TEXT,last_run_at TEXT,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS health_notifications (id TEXT PRIMARY KEY,severity TEXT NOT NULL,code TEXT NOT NULL,title TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL,acknowledged_at TEXT,generated_task_id TEXT);
      CREATE TABLE IF NOT EXISTS diagnostic_reports (id TEXT PRIMARY KEY,generated_at TEXT NOT NULL,health_score INTEGER NOT NULL,status TEXT NOT NULL,file_path TEXT,sha256 TEXT NOT NULL,size_bytes INTEGER NOT NULL);
      CREATE TABLE IF NOT EXISTS maintenance_history (id TEXT PRIMARY KEY,operation TEXT NOT NULL,success INTEGER NOT NULL,message TEXT NOT NULL,started_at TEXT NOT NULL,completed_at TEXT NOT NULL,duration_ms INTEGER NOT NULL,source TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS export_artifacts (id TEXT PRIMARY KEY,kind TEXT NOT NULL,format TEXT NOT NULL,file_path TEXT NOT NULL,sha256 TEXT NOT NULL,size_bytes INTEGER NOT NULL,record_count INTEGER,created_at TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS system_health_history (id TEXT PRIMARY KEY,score INTEGER NOT NULL,grade TEXT NOT NULL,system_status TEXT NOT NULL,deductions INTEGER NOT NULL,captured_at TEXT NOT NULL);
      CREATE INDEX IF NOT EXISTS idx_system_health_history_captured ON system_health_history(captured_at);
      CREATE TABLE IF NOT EXISTS diagnostic_archives (id TEXT PRIMARY KEY,created_at TEXT NOT NULL,from_at TEXT NOT NULL,to_at TEXT NOT NULL,entry_count INTEGER NOT NULL,file_path TEXT NOT NULL,sha256 TEXT NOT NULL,size_bytes INTEGER NOT NULL);
      CREATE TABLE IF NOT EXISTS ai_consents (id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,purpose TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,status TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT,created_at TEXT NOT NULL,UNIQUE(account_id,purpose,resource_type,resource_id));
      CREATE INDEX IF NOT EXISTS idx_people_family ON people(family_id);
      CREATE INDEX IF NOT EXISTS idx_events_family_date ON events(family_id, start_at DESC);
      CREATE INDEX IF NOT EXISTS idx_locations_family ON locations(family_id);
      CREATE INDEX IF NOT EXISTS idx_relations_family ON relations(family_id);
      CREATE INDEX IF NOT EXISTS idx_archive_family_created ON archive_items(family_id, created_at DESC);
      CREATE INDEX IF NOT EXISTS idx_finance_family_date ON finance_records(family_id, occurred_at DESC);
      CREATE INDEX IF NOT EXISTS idx_finance_owner_date ON finance_records(owner_person_id, occurred_at DESC);
      CREATE INDEX IF NOT EXISTS idx_health_family_date ON health_records(family_id, occurred_at DESC);
      CREATE INDEX IF NOT EXISTS idx_health_owner_date ON health_records(owner_person_id, occurred_at DESC);
      CREATE INDEX IF NOT EXISTS idx_life_family_due ON life_records(family_id, due_at);
      CREATE INDEX IF NOT EXISTS idx_diagnostics_occurred ON diagnostic_entries(occurred_at DESC);
      CREATE INDEX IF NOT EXISTS idx_performance_sampled ON performance_samples(sampled_at DESC);
      CREATE INDEX IF NOT EXISTS idx_backup_runs_started ON backup_runs(started_at DESC);
      CREATE INDEX IF NOT EXISTS idx_background_tasks_started ON background_tasks(started_at DESC);
      CREATE INDEX IF NOT EXISTS idx_task_queue_dispatch ON task_queue(status, priority, created_at);
      CREATE INDEX IF NOT EXISTS idx_audit_occurred ON audit_log(occurred_at DESC);
      CREATE INDEX IF NOT EXISTS idx_maintenance_started ON maintenance_history(started_at DESC);
      CREATE INDEX IF NOT EXISTS idx_health_notifications_created ON health_notifications(created_at DESC);
